-- Raw model predictions from ML inference pipeline
-- This table is the landing zone for predictions generated by the beat-the-streak-ml repo
-- Populated daily by the ML inference workflow

CREATE TABLE IF NOT EXISTS `project-7dd4e548-9904-449d-9b7.mlb_modeling.ml_mlb__model_predictions_raw` (
  player_id INT64 NOT NULL,
  game_date DATE NOT NULL,
  pitcher_id INT64 NOT NULL,
  game_id STRING NOT NULL,
  hit_probability FLOAT64 NOT NULL,
  model_version STRING NOT NULL,
  predicted_at TIMESTAMP NOT NULL
)
PARTITION BY game_date
CLUSTER BY player_id, pitcher_id
OPTIONS (
  description = 'Raw model predictions from ML inference pipeline. Populated daily by beat-the-streak-ml repo.',
  labels = [('source', 'ml_inference'), ('league', 'mlb')]
);
